-- Инфлүэнсер хэсэг
create table if not exists influencers (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  bio text,
  photo_url text,
  niches text[] not null default '{}',
  ig text, ig_followers int,
  fb_url text, fb_followers int,
  tiktok text, tiktok_followers int,
  youtube text, yt_followers int,
  reach int generated always as (coalesce(ig_followers,0)+coalesce(fb_followers,0)+coalesce(tiktok_followers,0)+coalesce(yt_followers,0)) stored,
  contact text,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists influencers_status_reach on influencers(status, reach desc);
alter table influencers enable row level security;
drop policy if exists "public approved influencers" on influencers;
create policy "public approved influencers" on influencers for select using (status = 'approved');
revoke select on influencers from anon, authenticated;
grant select (id,slug,name,bio,photo_url,niches,ig,ig_followers,fb_url,fb_followers,tiktok,tiktok_followers,youtube,yt_followers,reach,status,created_at) on influencers to anon, authenticated;
alter table events add column if not exists influencer_id uuid references influencers on delete cascade;
on conflict (slug) do nothing;
select count(*), sum(case when fb_url is not null then 1 else 0 end) fb from influencers;
